        static string Fallback(string key)
        {
            Dictionary<string, string> en;
            string v;
            if (D.TryGetValue("en", out en) && en.TryGetValue(key, out v)) return v;
            Dictionary<string, string> tr;
            if (D.TryGetValue("tr", out tr) && tr.TryGetValue(key, out v)) return v;
            return key;
        }

        public static string Get(string lang, string key)
        {
            Dictionary<string, string> m;
            string v;
            if (!string.IsNullOrEmpty(lang) && D.TryGetValue(lang, out m) && m.TryGetValue(key, out v)) return v;
            return Fallback(key);
        }

        public static string CultureOf(string lang)
        {
            for (int i = 0; i < Codes.Length; i++)
                if (Codes[i] == lang) return Cultures[i];
            return "en-US";
        }
